import java.util.*;

public class GregAndFriends {
    static int totalA, totalB, n, k;
    static long MOD = 1000000007;
    static long[][] choose = new long[100][100];
    static Map<Integer, Pair> states = new HashMap<>();
    static Queue<Integer> queue = new LinkedList<>();
    static class Pair {
        int depth;
        long waysCount;
        Pair(int d, long w) {
            depth = d;
            waysCount = w;
        }
    }
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        k = scanner.nextInt();
        totalA = 0;
        totalB = 0;
        for(int i = 0; i < n; i++) {
            int val = scanner.nextInt();
            if(val == 50) totalA++;
            else totalB++;
        }
        scanner.close();
        prepareChoose();
        int startState = 1000000 + 100 * totalA + totalB;
        queue.add(startState);
        states.put(startState, new Pair(0, 1));
        while(!queue.isEmpty()) {
            processState(queue.poll());
        }
        if(states.containsKey(0))
            System.out.println(states.get(0).depth + "\n" + states.get(0).waysCount);
        else
            System.out.println("-1\n0");
    }
    static void processState(int state) {
        int boatSide = state / 1000000;
        int aCount = (state % 1000000) / 100;
        int bCount = state % 100;
        if(boatSide > 0) {
            for(int i = aCount; i >= 0 && 50 * (aCount - i) <= k; i--) {
                for(int j = bCount; j >= 0 && 50 * (aCount - i) + 100 * (bCount - j) <= k; j--) {
                    if(i != aCount || j != bCount)
                        updateState(i, j, boatSide, state, choose[aCount][i] * choose[bCount][j] % MOD);
                }
            }
        } else {
            for(int i = aCount; i <= totalA && 50 * (i - aCount) <= k; i++) {
                for(int j = bCount; j <= totalB && 50 * (i - aCount) + 100 * (j - bCount) <= k; j++) {
                    if(i != aCount || j != bCount)
                        updateState(i, j, boatSide, state, choose[totalA - aCount][i - aCount] * choose[totalB - bCount][j - bCount] % MOD);
                }
            }
        }
    }
    static void updateState(int i, int j, int side, int prevState, long waysEdge) {
        int newState = 1000000 * (1 - side) + i * 100 + j;
        int newDepth = states.get(prevState).depth + 1;
        if(!states.containsKey(newState)) {
            states.put(newState, new Pair(newDepth, 0));
            queue.add(newState);
        }
        if(states.get(newState).depth == newDepth)
            states.get(newState).waysCount = (states.get(newState).waysCount + states.get(prevState).waysCount * waysEdge % MOD) % MOD;
    }
    static void prepareChoose() {
        for(int i=0; i<100; i++) choose[i][0] = 1;
        for(int i=1; i<100; i++) {
            for(int j=1; j<=i; j++) {
                choose[i][j] = (choose[i-1][j-1] + choose[i-1][j]) % MOD;
            }
        }
    }
}
